	input wire clk_i;
	output wire clk_o;
	assign clk_o = ~clk_i;
endmodule
module tc_clk_mux2 (
	clk0_i,
	clk1_i,
	clk_sel_i,
	clk_o
);
	input wire clk0_i;
	input wire clk1_i;
	input wire clk_sel_i;
	output wire clk_o;
	assign clk_o = (clk_sel_i ? clk1_i : clk0_i);
endmodule
module tc_clk_xor2 (
	clk0_i,
	clk1_i,
	clk_o
);
	input wire clk0_i;
	input wire clk1_i;
	output wire clk_o;
	assign clk_o = clk0_i ^ clk1_i;
endmodule
module tc_clk_or2 (
	clk0_i,
	clk1_i,
	clk_o
