		.ctrl_addr_valid(ctrl_addr_valid),
		.ctrl_data_rx(ctrl_data_rx),
		.ctrl_data_rx_valid(ctrl_data_rx_valid),
		.ctrl_data_tx(ctrl_data_tx),
		.ctrl_data_tx_ready(ctrl_data_tx_ready),
		.wrap_length(wrap_length)
	);
	spi_slave_dc_fifo #(.DATA_WIDTH(32)) u_dcfifo_rx(
		.clk_a(spi_sclk_i),
		.rstn_a(obi_rstn_i),
		.data_a(ctrl_data_rx),
		.valid_a(ctrl_data_rx_valid),
		.ready_a(),
		.clk_b(obi_clk_i),
		.rstn_b(obi_rstn_i),
		.data_b(fifo_data_rx),
		.valid_b(fifo_data_rx_valid),
		.ready_b(fifo_data_rx_ready)
	);
	spi_slave_dc_fifo #(.DATA_WIDTH(32)) u_dcfifo_tx(
		.clk_a(obi_clk_i),
		.rstn_a(obi_rstn_i),
		.data_a(fifo_data_tx),
		.valid_a(fifo_data_tx_valid),
		.ready_a(fifo_data_tx_ready),
		.clk_b(spi_sclk_i),
		.rstn_b(obi_rstn_i),
		.data_b(ctrl_data_tx),
		.valid_b(),
		.ready_b(ctrl_data_tx_ready)
	);
	spi_slave_obi_plug #(
		.OBI_ADDR_WIDTH(OBI_ADDR_WIDTH),
		.OBI_DATA_WIDTH(OBI_DATA_WIDTH)
	) u_obiplug(
		.obi_aclk(obi_clk_i),
		.obi_aresetn(obi_rstn_i),
		.obi_master_req(obi_master_req_o),
		.obi_master_gnt(obi_master_gnt_i),
		.obi_master_addr(obi_master_addr_o),
		.obi_master_we(obi_master_we_o),
		.obi_master_w_data(obi_master_w_data_o),
		.obi_master_be(obi_master_be_o),
		.obi_master_r_valid(obi_master_r_valid_i),
		.obi_master_r_data(obi_master_r_data_i),
		.rxtx_addr(addr_sync),
		.rxtx_addr_valid(addr_valid_sync),
		.start_tx(rd_wr_sync & addr_valid_sync),
		.cs(cs_sync),
		.tx_data(fifo_data_tx),
		.tx_valid(fifo_data_tx_valid),
		.tx_ready(fifo_data_tx_ready),
		.rx_data(fifo_data_rx),
		.rx_valid(fifo_data_rx_valid),
		.rx_ready(fifo_data_rx_ready),
		.wrap_length(wrap_length)
	);
	spi_slave_syncro #(.AXI_ADDR_WIDTH(OBI_ADDR_WIDTH)) u_syncro(
		.sys_clk(obi_clk_i),
		.rstn(obi_rstn_i),
		.cs(spi_cs_i),
		.address(ctrl_addr),
		.address_valid(ctrl_addr_valid),
		.rd_wr(ctrl_rd_wr),
		.cs_sync(cs_sync),
		.address_sync(addr_sync),
		.address_valid_sync(addr_valid_sync),
		.rd_wr_sync(rd_wr_sync)
	);
	assign test_mode = 1'b0;
endmodule
module spi_slave_obi_plug (
	obi_aclk,
	obi_aresetn,
	obi_master_req,
	obi_master_gnt,
	obi_master_addr,
	obi_master_we,
	obi_master_w_data,
	obi_master_be,
	obi_master_r_valid,
	obi_master_r_data,
	rxtx_addr,
	rxtx_addr_valid,
	start_tx,
	cs,
	tx_data,
	tx_valid,
	tx_ready,
	rx_data,
	rx_valid,
	rx_ready,
	wrap_length
);
	reg _sv2v_0;
	parameter OBI_ADDR_WIDTH = 32;
	parameter OBI_DATA_WIDTH = 32;
	input wire obi_aclk;
	input wire obi_aresetn;
	output reg obi_master_req;
	input wire obi_master_gnt;
	output wire [OBI_ADDR_WIDTH - 1:0] obi_master_addr;
	output reg obi_master_we;
	output wire [OBI_DATA_WIDTH - 1:0] obi_master_w_data;
	output wire [3:0] obi_master_be;
	input wire obi_master_r_valid;
	input wire [OBI_DATA_WIDTH - 1:0] obi_master_r_data;
	input wire [OBI_ADDR_WIDTH - 1:0] rxtx_addr;
	input wire rxtx_addr_valid;
	input wire start_tx;
	input wire cs;
	output wire [31:0] tx_data;
	output reg tx_valid;
	input wire tx_ready;
	input wire [31:0] rx_data;
	input wire rx_valid;
	output reg rx_ready;
	input wire [15:0] wrap_length;
	reg [OBI_ADDR_WIDTH - 1:0] curr_addr;
	reg [OBI_ADDR_WIDTH - 1:0] next_addr;
	reg [31:0] curr_data_rx;
	reg [OBI_DATA_WIDTH - 1:0] curr_data_tx;
	reg sample_fifo;
	reg sample_obidata;
	reg sample_rxtx_state;
	reg rxtx_state;
	reg [0:0] curr_rxtx_state;
	reg incr_addr_w;
	reg incr_addr_r;
	reg [15:0] tx_counter;
	wire [15:0] wrap_length_t;
	reg [1:0] OBI_CS;
	reg [1:0] OBI_NS;
	assign wrap_length_t = (wrap_length == 0 ? 16'h0001 : wrap_length);
	always @(posedge obi_aclk or negedge obi_aresetn)
		if (obi_aresetn == 0) begin
			OBI_CS <= 2'd0;
			curr_data_rx <= 'h0;
			curr_data_tx <= 'h0;
			curr_addr <= 'h0;
			curr_rxtx_state <= 'h0;
		end
		else begin
			OBI_CS <= OBI_NS;
			if (sample_fifo)
				curr_data_rx <= rx_data;
			if (sample_obidata)
				curr_data_tx <= obi_master_r_data;
			if (sample_rxtx_state)
				curr_rxtx_state <= rxtx_state;
			if (rxtx_addr_valid)
				curr_addr <= rxtx_addr;
			else if (incr_addr_w | incr_addr_r)
				curr_addr <= next_addr;
		end
	always @(posedge obi_aclk or negedge obi_aresetn)
		if (obi_aresetn == 1'b0)
			tx_counter <= 16'h0000;
		else if (start_tx)
			tx_counter <= 16'h0000;
		else if (incr_addr_w | incr_addr_r) begin
			if (tx_counter == (wrap_length_t - 1))
				tx_counter <= 16'h0000;
			else
				tx_counter <= tx_counter + 16'h0001;
		end
	always @(*) begin
		if (_sv2v_0)
			;
		next_addr = 32'b00000000000000000000000000000000;
		if (rxtx_addr_valid)
			next_addr = rxtx_addr;
		else if (tx_counter == (wrap_length_t - 1))
			next_addr = rxtx_addr;
		else
			next_addr = curr_addr + 32'h00000004;
	end
	always @(*) begin
		if (_sv2v_0)
			;
		OBI_NS = 2'd0;
		sample_fifo = 1'b0;
		rx_ready = 1'b0;
		tx_valid = 1'b0;
		obi_master_req = 1'b0;
		obi_master_we = 1'b0;
		sample_obidata = 1'b0;
		sample_rxtx_state = 1'b0;
		rxtx_state = 1'b0;
		incr_addr_w = 1'b0;
		incr_addr_r = 1'b0;
		case (OBI_CS)
			2'd0:
				if (rx_valid) begin
					sample_fifo = 1'b1;
					rx_ready = 1'b1;
					rxtx_state = 1'b1;
					sample_rxtx_state = 1'b1;
					OBI_NS = 2'd1;
				end
				else if (start_tx && !cs) begin
					rxtx_state = 1'b0;
					sample_rxtx_state = 1'b1;
					OBI_NS = 2'd1;
				end
				else
					OBI_NS = 2'd0;
			2'd1: begin
				if (curr_rxtx_state == 1'b1)
					obi_master_we = 1'b1;
				obi_master_req = 1'b1;
				if (obi_master_gnt && ((tx_ready && (curr_rxtx_state == 1'b0)) || (curr_rxtx_state == 1'b1)))
					OBI_NS = 2'd2;
				else
					OBI_NS = 2'd1;
			end
			2'd2:
				if (obi_master_r_valid) begin
					OBI_NS = 2'd0;
					if (curr_rxtx_state == 1'b0) begin
						sample_obidata = 1'b1;
						OBI_NS = 2'd3;
					end
					else
						incr_addr_w = 1'b1;
				end
				else
					OBI_NS = 2'd2;
			2'd3: begin
				tx_valid = 1'b1;
				if (cs)
					OBI_NS = 2'd0;
				else if (tx_ready) begin
					if (tx_counter == (wrap_length_t - 1))
						OBI_NS = 2'd0;
					else
						OBI_NS = 2'd1;
					incr_addr_r = 1'b1;
				end
				else
					OBI_NS = 2'd3;
			end
		endcase
	end
	assign tx_data = curr_data_tx;
	assign obi_master_addr = curr_addr;
	assign obi_master_w_data = curr_data_rx;
	assign obi_master_be = 4'b1111;
	initial _sv2v_0 = 0;
endmodule
module spi_slave_cmd_parser (
	cmd,
	get_addr,
	get_data,
	send_data,
	enable_cont,
	enable_regs,
	wait_dummy,
	reg_sel
);
	reg _sv2v_0;
	input wire [7:0] cmd;
	output reg get_addr;
	output reg get_data;
	output reg send_data;
	output reg enable_cont;
	output reg enable_regs;
	output reg wait_dummy;
	output reg [1:0] reg_sel;
	always @(*) begin
		if (_sv2v_0)
			;
		get_addr = 0;
		get_data = 0;
		send_data = 0;
		enable_cont = 0;
		enable_regs = 1'b0;
		wait_dummy = 0;
		reg_sel = 2'b00;
		case (cmd)
			8'h02: begin
				get_addr = 1;
				get_data = 1;
				send_data = 0;
				enable_cont = 1'b1;
				enable_regs = 1'b0;
				wait_dummy = 0;
				reg_sel = 2'b00;
			end
			8'h07: begin
				get_addr = 0;
				get_data = 0;
				send_data = 1;
				enable_cont = 0;
				enable_regs = 1'b1;
				wait_dummy = 0;
				reg_sel = 2'b00;
			end
			8'h0b: begin
				get_addr = 1;
				get_data = 0;
				send_data = 1;
				enable_cont = 1'b1;
				enable_regs = 1'b0;
				wait_dummy = 1;
				reg_sel = 2'b00;
			end
			8'h11: begin
				get_addr = 1'b0;
				get_data = 1'b1;
				send_data = 1'b0;
				enable_cont = 1'b0;
				enable_regs = 1'b1;
				wait_dummy = 1'b0;
				reg_sel = 2'b00;
			end
			8'h20: begin
				get_addr = 1'b0;
				get_data = 1'b1;
				send_data = 1'b0;
				enable_cont = 1'b0;
				enable_regs = 1'b1;
				wait_dummy = 1'b0;
				reg_sel = 2'b01;
			end
			8'h21: begin
				get_addr = 1'b0;
				get_data = 1'b0;
				send_data = 1'b1;
				enable_cont = 1'b0;
				enable_regs = 1'b1;
				wait_dummy = 1'b0;
				reg_sel = 2'b01;
			end
			8'h30: begin
				get_addr = 1'b0;
				get_data = 1'b1;
				send_data = 1'b0;
				enable_cont = 1'b0;
				enable_regs = 1'b1;
				wait_dummy = 1'b0;
				reg_sel = 2'b10;
			end
			8'h31: begin
				get_addr = 1'b0;
				get_data = 1'b0;
				send_data = 1'b1;
				enable_cont = 1'b0;
				enable_regs = 1'b1;
				wait_dummy = 1'b0;
				reg_sel = 2'b10;
			end
			default: begin
				get_addr = 0;
				get_data = 1'b0;
				send_data = 0;
				enable_cont = 0;
				enable_regs = 1'b0;
				wait_dummy = 0;
				reg_sel = 2'b00;
			end
		endcase
	end
	initial _sv2v_0 = 0;
endmodule
module spi_slave_controller (
	sclk,
	sys_rstn,
	cs,
	rx_counter,
	rx_counter_upd,
	rx_data,
	rx_data_valid,
	tx_counter,
	tx_counter_upd,
	tx_data,
	tx_data_valid,
	tx_done,
	ctrl_rd_wr,
	ctrl_addr,
	ctrl_addr_valid,
	ctrl_data_rx,
	ctrl_data_rx_valid,
	ctrl_data_tx,
	ctrl_data_tx_ready,
	wrap_length
);
	reg _sv2v_0;
	parameter DUMMY_CYCLES = 32;
	input wire sclk;
	input wire sys_rstn;
	input wire cs;
	output reg [7:0] rx_counter;
	output reg rx_counter_upd;
	input wire [31:0] rx_data;
	input wire rx_data_valid;
	output reg [7:0] tx_counter;
	output reg tx_counter_upd;
	output reg [31:0] tx_data;
	output reg tx_data_valid;
	input wire tx_done;
	output wire ctrl_rd_wr;
	output wire [31:0] ctrl_addr;
	output reg ctrl_addr_valid;
	output wire [31:0] ctrl_data_rx;
	output reg ctrl_data_rx_valid;
	input wire [31:0] ctrl_data_tx;
	output reg ctrl_data_tx_ready;
	output wire [15:0] wrap_length;
	localparam REG_SIZE = 8;
	reg [2:0] state;
	reg [2:0] state_next;
	wire [7:0] command;
	reg decode_cmd_comb;
	reg [31:0] addr_reg;
	reg [7:0] cmd_reg;
	reg sample_ADDR;
	reg sample_CMD;
	wire get_addr;
	wire wait_dummy;
	wire get_data;
	wire send_data;
	wire enable_cont;
	wire enable_regs;
	wire [1:0] reg_sel;
	wire [7:0] reg_data;
	reg reg_valid;
	reg ctrl_data_tx_ready_next;
	reg [7:0] tx_counter_next;
	reg tx_counter_upd_next;
	reg tx_data_valid_next;
	reg tx_done_reg;
	wire [7:0] s_dummy_cycles;
	assign command = (decode_cmd_comb ? rx_data[7:0] : cmd_reg);
	spi_slave_cmd_parser u_cmd_parser(
		.cmd(command),
		.get_addr(get_addr),
		.get_data(get_data),
		.send_data(send_data),
		.wait_dummy(wait_dummy),
		.enable_cont(enable_cont),
		.enable_regs(enable_regs),
		.reg_sel(reg_sel)
	);
	spi_slave_regs #(
		.REG_SIZE(REG_SIZE),
		.DUMMY_CYCLES(DUMMY_CYCLES)
	) u_spiregs(
		.sclk(sclk),
		.rstn(sys_rstn),
		.wr_data(rx_data[7:0]),
		.wr_addr(reg_sel),
		.wr_data_valid(reg_valid),
		.rd_data(reg_data),
		.rd_addr(reg_sel),
		.dummy_cycles(s_dummy_cycles),
		.wrap_length(wrap_length)
	);
	always @(*) begin
		if (_sv2v_0)
			;
		rx_counter = 8'h1f;
		rx_counter_upd = 0;
		tx_counter_next = 8'h1f;
		tx_counter_upd_next = 0;
		decode_cmd_comb = 1'b0;
		sample_ADDR = 1'b0;
		sample_CMD = 1'b0;
		ctrl_data_rx_valid = 1'b0;
		ctrl_data_tx_ready_next = 1'b0;
		reg_valid = 1'b0;
		tx_data_valid_next = 1'b0;
		state_next = state;
		case (state)
			3'd0: begin
				decode_cmd_comb = 1'b1;
				ctrl_data_tx_ready_next = 1'b1;
				if (rx_data_valid) begin
					sample_CMD = 1'b1;
					if (get_addr) begin
						state_next = 3'd1;
						rx_counter_upd = 1;
						rx_counter = 8'h1f;
					end
					else if (get_data) begin
						state_next = 3'd3;
						rx_counter_upd = 1;
						if (enable_regs)
							rx_counter = 8'h07;
					end
					else begin
						state_next = 3'd2;
						tx_counter_upd_next = 1;
						tx_data_valid_next = 1'b1;
						tx_counter_next = 8'h1f;
						if (~enable_regs)
							ctrl_data_tx_ready_next = 1'b1;
					end
				end
				else
					state_next = 3'd0;
			end
			3'd1: begin
				ctrl_data_tx_ready_next = 1'b1;
				if (rx_data_valid) begin
					sample_ADDR = 1'b1;
					if (wait_dummy) begin
						state_next = 3'd4;
						rx_counter = s_dummy_cycles;
						rx_counter_upd = 1;
					end
					else begin
						state_next = 3'd3;
						rx_counter_upd = 1;
						rx_counter = 8'h1f;
					end
				end
				else
					state_next = 3'd1;
			end
			3'd4:
				if (rx_data_valid) begin
					state_next = 3'd2;
					tx_counter_next = 8'h1f;
					tx_counter_upd_next = 1;
					tx_data_valid_next = 1'b1;
					if (~enable_regs)
						ctrl_data_tx_ready_next = 1'b1;
				end
				else
					state_next = 3'd4;
			3'd3:
				if (rx_data_valid) begin
					if (enable_regs)
						reg_valid = 1'b1;
					else
						ctrl_data_rx_valid = 1'b1;
					if (enable_cont) begin
						state_next = 3'd3;
						rx_counter = 8'h1f;
						rx_counter_upd = 1;
					end
					else begin
						state_next = 3'd0;
						rx_counter = 8'h07;
						rx_counter_upd = 1;
					end
				end
				else
					state_next = 3'd3;
			3'd2:
				if (tx_done_reg) begin
					if (enable_cont) begin
						state_next = 3'd2;
						tx_counter_next = 8'h1f;
						tx_counter_upd_next = 1;
						tx_data_valid_next = 1'b1;
						if (~enable_regs)
							ctrl_data_tx_ready_next = 1'b1;
					end
					else begin
						state_next = 3'd0;
						rx_counter = 8'h07;
						rx_counter_upd = 1;
					end
				end
				else
					state_next = 3'd2;
			default: state_next = state;
		endcase
	end
	always @(posedge sclk or posedge cs)
		if (cs == 1'b1)
			state <= 3'd0;
		else
			state <= state_next;
	always @(posedge sclk or posedge cs)
		if (cs == 1'b1) begin
			addr_reg <= 'h0;
			cmd_reg <= 'h0;
			tx_done_reg <= 1'b0;
			ctrl_addr_valid <= 1'b0;
			tx_counter_upd <= 1'b0;
			tx_data_valid <= 1'b0;
			ctrl_data_tx_ready <= 1'b0;
			tx_counter <= 'h0;
			tx_data <= 'h0;
		end
		else begin
			if (sample_ADDR)
				addr_reg <= rx_data;
			if (sample_CMD)
				cmd_reg <= rx_data[7:0];
			ctrl_addr_valid <= sample_ADDR;
			tx_counter_upd <= tx_counter_upd_next;
			tx_counter <= tx_counter_next;
			tx_data_valid <= tx_data_valid_next;
			tx_done_reg <= tx_done;
			ctrl_data_tx_ready <= ctrl_data_tx_ready_next;
			tx_data <= (enable_regs ? {24'b000000000000000000000000, reg_data} : ctrl_data_tx);
		end
	assign ctrl_data_rx = rx_data;
	assign ctrl_addr = addr_reg;
	assign ctrl_rd_wr = send_data;
	initial _sv2v_0 = 0;
endmodule
module spi_slave_dc_fifo (
	clk_a,
	rstn_a,
	data_a,
	valid_a,
	ready_a,
	clk_b,
	rstn_b,
	data_b,
	valid_b,
	ready_b
);
	parameter DATA_WIDTH = 32;
	input wire clk_a;
	input wire rstn_a;
	input wire [DATA_WIDTH - 1:0] data_a;
	input wire valid_a;
	output wire ready_a;
	input wire clk_b;
	input wire rstn_b;
	output wire [DATA_WIDTH - 1:0] data_b;
	output wire valid_b;
	input wire ready_b;
	cdc_fifo_gray_EC851_C006F #(
		.T_DATA_WIDTH(DATA_WIDTH),
		.WIDTH(32),
		.LOG_DEPTH(4),
		.SYNC_STAGES(2)
	) i_cdc_fifo_gray(
		.src_rst_ni(rstn_a),
		.src_clk_i(clk_a),
		.src_data_i(data_a),
		.src_valid_i(valid_a),
		.src_ready_o(ready_a),
		.dst_rst_ni(rstn_b),
		.dst_clk_i(clk_b),
		.dst_data_o(data_b),
		.dst_valid_o(valid_b),
		.dst_ready_i(ready_b)
	);
endmodule
module spi_slave_regs (
	sclk,
	rstn,
	wr_data,
	wr_addr,
	wr_data_valid,
	rd_data,
	rd_addr,
	dummy_cycles,
	wrap_length
);
	reg _sv2v_0;
	parameter REG_SIZE = 8;
	parameter DUMMY_CYCLES = 32;
	input wire sclk;
	input wire rstn;
	input wire [REG_SIZE - 1:0] wr_data;
	input wire [1:0] wr_addr;
	input wire wr_data_valid;
	output reg [REG_SIZE - 1:0] rd_data;
	input wire [1:0] rd_addr;
	output wire [7:0] dummy_cycles;
	output wire [15:0] wrap_length;
	reg [REG_SIZE - 1:0] reg0;
	reg [REG_SIZE - 1:0] reg1;
	reg [REG_SIZE - 1:0] reg2;
	assign dummy_cycles = reg0;
	assign wrap_length = {reg2, reg1};
	always @(*) begin
		if (_sv2v_0)
			;
		rd_data = reg0;
		case (rd_addr)
			2'b00: rd_data = reg0;
			2'b01: rd_data = reg1;
			2'b10: rd_data = reg2;
