		else if (counter_trgt == 8'h01)
			counter_trgt_next = 8'h07;
		else
			counter_trgt_next = counter_trgt;
		if (counter_in_upd)
			running_next = 1'b1;
		else if (counter == counter_trgt)
			running_next = 1'b0;
		else
			running_next = running;
		if (running) begin
			if (counter == counter_trgt) begin
				counter_next = 'h0;
				data_ready = 1'b1;
			end
			else begin
				counter_next = counter + 1;
				data_ready = 1'b0;
			end
			data_int_next = {data_int[30:0], mosi};
		end
		else begin
			counter_next = counter;
			data_ready = 1'b0;
			data_int_next = data_int;
		end
