module spi_slave_tx (
	test_mode,
	sclk,
	cs,
	miso,
	counter_in,
	counter_in_upd,
	data,
	data_valid,
	done
);
	reg _sv2v_0;
	input wire test_mode;
	input wire sclk;
	input wire cs;
	output wire miso;
	input wire [7:0] counter_in;
	input wire counter_in_upd;
	input wire [31:0] data;
	input wire data_valid;
	output reg done;
	reg [31:0] data_int;
	reg [31:0] data_int_next;
	reg [7:0] counter;
	reg [7:0] counter_trgt;
	reg [7:0] counter_next;
	reg [7:0] counter_trgt_next;
	reg running;
	reg running_next;
	wire sclk_inv;
	wire sclk_test;
	assign miso = data_int[31];
