		if (_sv2v_0)
			;
		done = 1'b0;
		if (counter_in_upd)
			counter_trgt_next = counter_in;
		else
			counter_trgt_next = counter_trgt;
		if (counter_in_upd)
			running_next = 1'b1;
		else if (counter == counter_trgt)
			running_next = 1'b0;
		else
			running_next = running;
		if (running || counter_in_upd) begin
			if (counter == counter_trgt) begin
				done = 1'b1;
				counter_next = 0;
			end
			else
				counter_next = counter + 1;
			if (data_valid)
				data_int_next = data;
			else
				data_int_next = {data_int[30:0], 1'b0};
		end
		else begin
			counter_next = counter;
			data_int_next = data_int;
		end
	end
	pulp_clock_inverter clk_inv_i(
		.clk_i(sclk),
		.clk_o(sclk_inv)
	);
	pulp_clock_mux2 clk_mux_i(
		.clk0_i(sclk_inv),
		.clk1_i(sclk),
		.clk_sel_i(test_mode),
		.clk_o(sclk_test)
	);
	always @(posedge sclk_test or posedge cs)
		if (cs == 1'b1) begin
			counter <= 'h0;
			counter_trgt <= 'h7;
			data_int <= 'h0;
			running <= 1'b0;
		end
		else begin
			counter <= counter_next;
			counter_trgt <= counter_trgt_next;
			data_int <= data_int_next;
			running <= running_next;
		end
	initial _sv2v_0 = 0;
endmodule
module rv_plic_gateway (
