	reg [31:0] sub_word;
	reg [31:0] nw0;
	reg [31:0] nw1;
	reg [31:0] nw2;
	reg [31:0] nw3;
	reg [7:0] sbox_in0;
	reg [7:0] sbox_in1;
	reg [7:0] sbox_in2;
	reg [7:0] sbox_in3;
	wire [7:0] sbox_out0;
	wire [7:0] sbox_out1;
	wire [7:0] sbox_out2;
	wire [7:0] sbox_out3;
	aes_sbox sbox0(
		.in(sbox_in0),
		.out(sbox_out0)
	);
	aes_sbox sbox1(
		.in(sbox_in1),
		.out(sbox_out1)
	);
	aes_sbox sbox2(
		.in(sbox_in2),
		.out(sbox_out2)
	);
	aes_sbox sbox3(
		.in(sbox_in3),
		.out(sbox_out3)
	);
	always @(*) begin
		w0 = key_reg[127:96];
		w1 = key_reg[95:64];
		w2 = key_reg[63:32];
		w3 = key_reg[31:0];
		t = {w3[23:16], w3[15:8], w3[7:0], w3[31:24]};
		sbox_in0 = t[31:24];
		sbox_in1 = t[23:16];
		sbox_in2 = t[15:8];
		sbox_in3 = t[7:0];
		sub_word = {sbox_out0, sbox_out1, sbox_out2, sbox_out3};
		nw0 = (w0 ^ sub_word) ^ {rcon, 24'h000000};
		nw1 = w1 ^ nw0;
		nw2 = w2 ^ nw1;
		nw3 = w3 ^ nw2;
	end
	function automatic [7:0] rcon_next;
		input reg [7:0] r;
		if (r[7])
			rcon_next = {r[6:0], 1'b0} ^ 8'h1b;
		else
			rcon_next = {r[6:0], 1'b0};
	endfunction
	always @(posedge clk or negedge rst_n)
		if (!rst_n) begin
			key_reg <= 128'h00000000000000000000000000000000;
			round_key <= 128'h00000000000000000000000000000000;
			round <= 4'd0;
			rcon <= 8'h01;
			valid <= 1'b0;
			done <= 1'b0;
		end
		else begin
			valid <= 1'b0;
			done <= 1'b0;
			if (start) begin
				key_reg <= key_in;
				round_key <= key_in;
				round <= 4'd0;
				rcon <= 8'h01;
				valid <= 1'b1;
			end
			else if (round < 4'd10) begin
				key_reg <= {nw0, nw1, nw2, nw3};
				round_key <= {nw0, nw1, nw2, nw3};
				round <= round + 4'd1;
				rcon <= rcon_next(rcon);
				valid <= 1'b1;
			end
			else
				done <= 1'b1;
