module i2c_fsm (
	clk_i,
	rst_ni,
	scl_i,
	scl_o,
	sda_i,
	sda_o,
	host_enable_i,
	target_enable_i,
	fmt_fifo_rvalid_i,
	fmt_fifo_wvalid_i,
	fmt_fifo_depth_i,
	fmt_fifo_rready_o,
	fmt_byte_i,
	fmt_flag_start_before_i,
	fmt_flag_stop_after_i,
	fmt_flag_read_bytes_i,
	fmt_flag_read_continue_i,
	fmt_flag_nak_ok_i,
	rx_fifo_wvalid_o,
	rx_fifo_wdata_o,
	tx_fifo_rvalid_i,
	tx_fifo_wvalid_i,
	tx_fifo_depth_i,
	tx_fifo_rready_o,
	tx_fifo_rdata_i,
	acq_fifo_wready_i,
	acq_fifo_wvalid_o,
	acq_fifo_wdata_o,
	host_idle_o,
	target_idle_o,
	thigh_i,
	tlow_i,
	t_r_i,
	t_f_i,
	thd_sta_i,
	tsu_sta_i,
	tsu_sto_i,
	tsu_dat_i,
	thd_dat_i,
	t_buf_i,
	stretch_timeout_i,
	timeout_enable_i,
	stretch_en_addr_i,
	stretch_en_tx_i,
	stretch_en_acq_i,
	stretch_stop_i,
	host_timeout_i,
	target_address0_i,
	target_mask0_i,
	target_address1_i,
	target_mask1_i,
	event_nak_o,
	event_scl_interference_o,
	event_sda_interference_o,
	event_stretch_timeout_o,
	event_sda_unstable_o,
	event_trans_complete_o,
	event_tx_empty_o,
	event_tx_nonempty_o,
	event_ack_stop_o,
	event_host_timeout_o
);
	reg _sv2v_0;
	input clk_i;
	input rst_ni;
	input scl_i;
	output wire scl_o;
	input sda_i;
	output wire sda_o;
	input host_enable_i;
	input target_enable_i;
	input fmt_fifo_rvalid_i;
	input fmt_fifo_wvalid_i;
	input [5:0] fmt_fifo_depth_i;
	output reg fmt_fifo_rready_o;
	input [7:0] fmt_byte_i;
	input fmt_flag_start_before_i;
	input fmt_flag_stop_after_i;
	input fmt_flag_read_bytes_i;
	input fmt_flag_read_continue_i;
	input fmt_flag_nak_ok_i;
	output reg rx_fifo_wvalid_o;
	output reg [7:0] rx_fifo_wdata_o;
	input tx_fifo_rvalid_i;
	input tx_fifo_wvalid_i;
	input [5:0] tx_fifo_depth_i;
	output reg tx_fifo_rready_o;
	input [7:0] tx_fifo_rdata_i;
	input wire acq_fifo_wready_i;
	output reg acq_fifo_wvalid_o;
	output reg [9:0] acq_fifo_wdata_o;
	output reg host_idle_o;
	output reg target_idle_o;
	input [15:0] thigh_i;
	input [15:0] tlow_i;
	input [15:0] t_r_i;
	input [15:0] t_f_i;
	input [15:0] thd_sta_i;
	input [15:0] tsu_sta_i;
	input [15:0] tsu_sto_i;
	input [15:0] tsu_dat_i;
	input [15:0] thd_dat_i;
	input [15:0] t_buf_i;
	input [30:0] stretch_timeout_i;
	input timeout_enable_i;
	input stretch_en_addr_i;
	input stretch_en_tx_i;
	input stretch_en_acq_i;
	input stretch_stop_i;
	input [31:0] host_timeout_i;
	input wire [6:0] target_address0_i;
	input wire [6:0] target_mask0_i;
	input wire [6:0] target_address1_i;
	input wire [6:0] target_mask1_i;
	output reg event_nak_o;
	output reg event_scl_interference_o;
	output reg event_sda_interference_o;
	output reg event_stretch_timeout_o;
	output reg event_sda_unstable_o;
	output reg event_trans_complete_o;
	output reg event_tx_empty_o;
	output reg event_tx_nonempty_o;
	output reg event_ack_stop_o;
	output wire event_host_timeout_o;
	reg [19:0] tcount_q;
	reg [19:0] tcount_d;
	reg load_tcount;
	reg [30:0] stretch;
	reg [2:0] bit_index;
	reg bit_decr;
	reg bit_clr;
	reg [8:0] byte_num;
	reg [8:0] byte_index;
	reg byte_decr;
	reg byte_clr;
	reg scl_temp;
	reg sda_temp;
	reg scl_i_q;
	reg sda_i_q;
	reg [7:0] read_byte;
	reg read_byte_clr;
	reg shift_data_en;
	reg no_stop;
	reg log_start;
	reg log_stop;
	reg restart;
	reg start_det;
	reg stop_det;
	wire address0_match;
	wire address1_match;
	wire address_match;
	reg [7:0] input_byte;
	reg input_byte_clr;
	reg [31:0] scl_high_cnt;
	reg [3:0] bit_idx;
	wire bit_ack;
	wire rw_bit;
	reg host_ack;
	reg [3:0] tcount_sel;
	function automatic [19:0] sv2v_cast_20;
		input reg [19:0] inp;
		sv2v_cast_20 = inp;
	endfunction
	always @(*) begin : counter_functions
		if (_sv2v_0)
			;
		tcount_d = tcount_q;
		if (load_tcount)
			(* full_case, parallel_case *)
			case (tcount_sel)
				4'd0: tcount_d = sv2v_cast_20(t_r_i) + sv2v_cast_20(tsu_sta_i);
				4'd1: tcount_d = sv2v_cast_20(t_f_i) + sv2v_cast_20(thd_sta_i);
				4'd6: tcount_d = sv2v_cast_20(thd_dat_i);
				4'd2: tcount_d = ((sv2v_cast_20(tlow_i) - sv2v_cast_20(t_r_i)) - sv2v_cast_20(tsu_dat_i)) - sv2v_cast_20(thd_dat_i);
				4'd3: tcount_d = sv2v_cast_20(t_r_i) + sv2v_cast_20(tsu_dat_i);
				4'd4: tcount_d = (sv2v_cast_20(t_r_i) + sv2v_cast_20(thigh_i)) + sv2v_cast_20(t_f_i);
				4'd5: tcount_d = sv2v_cast_20(t_f_i) + sv2v_cast_20(thd_dat_i);
				4'd7: tcount_d = (sv2v_cast_20(t_f_i) + sv2v_cast_20(tlow_i)) - sv2v_cast_20(thd_dat_i);
				4'd8: tcount_d = sv2v_cast_20(t_r_i) + sv2v_cast_20(tsu_sto_i);
				4'd9: tcount_d = (sv2v_cast_20(t_r_i) + sv2v_cast_20(t_buf_i)) - sv2v_cast_20(tsu_sta_i);
				4'd10: tcount_d = 20'h00001;
				default: tcount_d = 20'h00001;
			endcase
		else if (stretch == {31 {1'sb0}})
			tcount_d = tcount_q - 1'b1;
		else
			tcount_d = tcount_q;
	end
	always @(posedge clk_i or negedge rst_ni) begin : clk_counter
		if (!rst_ni)
			tcount_q <= 1'sb1;
		else
			tcount_q <= tcount_d;
	end
	always @(posedge clk_i or negedge rst_ni) begin : clk_stretch
		if (!rst_ni)
			stretch <= 1'sb0;
		else if (scl_temp && !scl_i)
			stretch <= stretch + 1'b1;
		else
			stretch <= 1'sb0;
	end
	always @(posedge clk_i or negedge rst_ni) begin : bit_counter
		if (!rst_ni)
			bit_index <= 3'd7;
		else if (bit_clr)
			bit_index <= 3'd7;
		else if (bit_decr)
			bit_index <= bit_index - 1'b1;
		else
			bit_index <= bit_index;
	end
	always @(posedge clk_i or negedge rst_ni) begin : read_register
		if (!rst_ni)
			read_byte <= 8'h00;
		else if (read_byte_clr)
			read_byte <= 8'h00;
		else if (shift_data_en)
			read_byte[7:0] <= {read_byte[6:0], sda_i};
	end
	function automatic [8:0] sv2v_cast_9;
		input reg [8:0] inp;
		sv2v_cast_9 = inp;
	endfunction
	always @(*) begin : byte_number
		if (_sv2v_0)
			;
		if (!fmt_flag_read_bytes_i)
			byte_num = 9'd0;
		else if (fmt_byte_i == {8 {1'sb0}})
			byte_num = 9'd256;
		else
			byte_num = sv2v_cast_9(fmt_byte_i);
	end
	always @(posedge clk_i or negedge rst_ni) begin : byte_counter
		if (!rst_ni)
			byte_index <= 1'sb0;
		else if (byte_clr)
			byte_index <= byte_num;
		else if (byte_decr)
			byte_index <= byte_index - 1'b1;
		else
			byte_index <= byte_index;
	end
	always @(posedge clk_i or negedge rst_ni) begin : bus_prev
		if (!rst_ni) begin
			scl_i_q <= 1'b1;
			sda_i_q <= 1'b1;
		end
		else begin
			scl_i_q <= scl_i;
			sda_i_q <= sda_i;
		end
	end
	always @(posedge clk_i or negedge rst_ni) begin : stop_state
		if (!rst_ni)
			no_stop <= 1'b0;
		else if (log_stop)
			no_stop <= 1'b0;
		else if (log_start)
			no_stop <= 1'b1;
		else
			no_stop <= no_stop;
	end
	always @(posedge clk_i or negedge rst_ni) begin : s_detect
		if (!rst_ni)
			start_det <= 1'b0;
		else if (scl_i_q && scl_i) begin
			if (sda_i_q && !sda_i)
				start_det <= 1'b1;
			else
				start_det <= 1'b0;
		end
		else
			start_det <= 1'b0;
	end
	always @(posedge clk_i or negedge rst_ni) begin : p_detect
		if (!rst_ni)
			stop_det <= 1'b0;
		else if (scl_i_q && scl_i) begin
			if (!sda_i_q && sda_i)
				stop_det <= 1'b1;
			else
				stop_det <= 1'b0;
		end
		else
			stop_det <= 1'b0;
	end
