	input [11:0] prescaler;
	input [7:0] step;
	output wire tick;
	output wire [63:0] mtime_d;
	input [63:0] mtime;
	input [(N * 64) - 1:0] mtimecmp;
	output wire [N - 1:0] intr;
	reg [11:0] tick_count;
